test("slow subscriber drops oldest, counted", async () => {
  const broker = new EventBusBroker({ queueCapacity: 4 });
  const sub = broker.subscribeLocal([]);
  for (let i = 1; i <= 6; i++) {
    broker.publishEvent([], enc(`m${i}`));
  }
  assert.equal(broker.stats().dropped, 2);
  assert.equal(sub.dropped, 2);
  const seqs = [];
  for (let i = 0; i < 4; i++) seqs.push(Number((await sub.take()).seq));
  assert.deepEqual(seqs, [3, 4, 5, 6]);
  sub.close();
  assert.equal(broker.stats().subscribers, 0);
});

