test("git log serde round-trips and is idempotent", () => {
  const repo = mkdtempSync(join(tmpdir(), "grpc-dc-eventbus-"));
  try {
    const broker = new EventBusBroker();
    const events = [
      broker.publishEvent([tagString(Tag.TOPIC, "orders")], enc("o1"), "test"),
      broker.publishEvent([tagString(Tag.TOPIC, "other")], enc("x1"), "test"),
      broker.publishEvent([tagString(Tag.TOPIC, "orders")], enc("o2"), "test"),
    ];
    const head1 = exportEvents(repo, events);
    const count = execFileSync("git", ["-C", repo, "rev-list", "--count", "grpc-dc-events"], {
      encoding: "utf8",
    }).trim();
    assert.equal(count, "3");
    assert.equal(exportEvents(repo, events), head1);
    const all = importEvents(repo);
    assert.deepEqual(all.map((e) => e.seq), [1n, 2n, 3n]);
    assert.deepEqual(all.map((e) => dec(e.payload)), ["o1", "x1", "o2"]);
    assert.ok(all.every((e) => e.publisherId === "test"));
    const ordersOnly = importEvents(repo, "grpc-dc-events", {
      filter: [tagString(Tag.TOPIC, "orders")],
    });
    assert.deepEqual(ordersOnly.map((e) => e.seq), [1n, 3n]);
    const window = importEvents(repo, "grpc-dc-events", { fromSeq: 1n, toSeq: 2n });
    assert.deepEqual(window.map((e) => e.seq), [2n]);
  } finally {
    rmSync(repo, { recursive: true, force: true });
  }
});
